import {esc,icon} from './utils.js';
import {codeBlock} from './code-renderer.js';
const descriptions={Variables:'Name a value, initialize it, and follow how it changes.',Printing:'Make your program show a result. Read output one expression at a time.',Operators:'Combine values with arithmetic and understand the order of operations.',Comments:'Write useful notes that explain why your code works this way.',Functions:'Give a reusable operation a name, pass inputs and return a result.',Collections:'Store several related values and learn how to access them.',Conditionals:'Choose a path with if and else by evaluating a condition.',Loops:'Repeat a task, track each iteration and check where the loop stops.',Strings:'Represent text, combine it and understand how characters are stored.',Input:'Read a value supplied by the user and check whether reading succeeded.',Pointers:'Work with addresses and distinguish an address from its value.','Memory allocation':'Request memory, check for failure and release resources safely.','Data types':'Choose a suitable representation for each kind of value.',Structures:'Group related fields into a single structured value.','Debugging basics':'Trace a small example and locate the first unexpected value.'};
export function learningHTML(catalog,state,bank=null,questions=[]){const heading=`<div class="page-head"><div><div class="eyebrow">START WITH THE FOUNDATIONS</div><h1>${bank?esc(bank.title)+' · step by step':'Your first line starts here.'}</h1><p>Small concepts. Clear examples. Practice at your own pace.</p></div></div>`;if(!bank)return heading+`<div class="learn-intro">${icon('bulb')}<div><h2>New to programming? You’re in the right place.</h2><p>Choose a language, open a topic, read an example, then try its questions. No prerequisites or locked lessons.</p></div></div><div class="collection-grid wide-grid">${catalog.filter(c=>c.group==='Languages').map(c=>`<a href="#/learn/${c.id}" class="collection"><span class="lang-icon" style="--tint:${c.color}">${esc(c.symbol)}</span><h3 style="margin-top:14px">${esc(c.title)}</h3><p>${c.topics.length} topics · ${c.count} questions</p><span class="text-btn">Open learning path ${icon('arrow')}</span></a>`).join('')}</div>`;
const order=['Variables','Data types','Printing','Input','Operators','Comments','Conditionals','Loops','Functions','Collections','Strings','Debugging basics'];const topics=[...bank.topics].sort((a,b)=>(order.includes(a)?order.indexOf(a):99)-(order.includes(b)?order.indexOf(b):99));return heading+`<div class="button-row" style="margin-bottom:20px"><a class="btn" href="#/learn">${icon('back')} All languages</a><a class="btn primary" href="#/config/${bank.id}">Custom ${esc(bank.title)} quiz ${icon('arrow')}</a></div><div class="lesson-list">${topics.map((t,i)=>{const qs=questions.filter(q=>q.topic===t),attempted=qs.filter(q=>state.questions[q.id]).length,correct=qs.filter(q=>state.questions[q.id]?.lastCorrect).length,example=qs.find(q=>q.code);return `<details class="lesson"><summary><span class="lesson-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(t)}</h3><small>${qs.length} questions · ${attempted} explored · ${correct} last answered correctly</small></div>${icon('back')}</summary><div class="lesson-body"><p>${esc(descriptions[t]||'Explore the core rules of '+t.toLowerCase()+' with focused questions and explanations.')}</p>${example?codeBlock(example.code,bank.title,state.settings):''}<div class="lesson-progress"><span style="width:${correct/qs.length*100}%"></span></div><a class="btn primary" href="#/config/${bank.id}?topic=${encodeURIComponent(t)}">Practice ${esc(t)} ${icon('arrow')}</a><p class="muted" style="font-size:11px;margin-top:12px">Answers and reasoning appear after you submit. You can repeat any topic whenever you want.</p></div></details>`}).join('')}</div>`}
